"use strict";webui.define("app-project-manager",{constructor(){const t=this;t._btnEdit=t.template.querySelector("#btn-edit"),t._btnRemove=t.template.querySelector("#btn-remove")},connected(){const t=this;t._btnEdit.addEventListener("click",async c=>{let e=webui.getData("app-current-project");if(!e||!e.value){webui.alert("No project is currently selected.","warning");return}webui.wait(()=>webui.querySelector('webui-input-text[name="projectName"]')?.setValue).then(()=>{webui.querySelector('webui-input-text[name="projectName"]').value=e.display}),webui.dialog({title:"Rename Project",content:`
                        <webui-flex column><webui-input-text name="projectName" label="New Project Name">
                        </webui-input-text></webui-flex>
                        `,confirm:"Rename",cancel:"Cancel",onconfirm:async(n,a)=>{let r=(Object.fromEntries(n).projectName||"").trim();if(!r)return a.alert("Project name cannot be empty."),!1;let i=await webui.proxy.renameProject(e.value,r,u=>a.alert(u));if(i)return webui.alert(i,"success"),webui.setData("app-current-project",{value:e.value,display:r}),!0}})}),t._btnRemove.addEventListener("click",async c=>{let e=webui.getData("app-current-project");if(!e||!e.value){webui.alert("No project is currently selected.","warning");return}webui.dialog({title:"Remove Project",content:`
                    <p>Are you sure you want to remove the project <strong>${webui.escapeForHTML(e.display)}</strong>?</p>
                    <p style="background: var(--color-danger); color: var(--color-danger-offset); padding: 0.25em 0.5em; border-radius: var(--corners);">This will only remove the project from Task Proxy. No files or folders will be deleted.</p>
                    `,confirm:"Remove",cancel:"Cancel",onconfirm:async(n,a)=>{let o=await webui.proxy.removeProject(e.value,r=>a.alert(r));if(o)return webui.alert(o,"success"),webui.setData("app-current-project",null),!0}})})},shadowTemplate:`
<style type="text/css">
:host {
    display: flex;
    gap: var(--padding);
    flex-wrap: wrap;
}
</style>
<webui-button id="btn-edit" theme="primary">Edit Name</webui-button>
<webui-button id="btn-remove" theme="danger">Remove Project</webui-button>
`});
